const tracks = [...myTracks];

const $ = id => document.getElementById(id);
const audio = $("audio"), grid = $("trackGrid");
let current = -1, playing = false, filter = "All", query = "", shuffle = false, repeat = false, view = "home";
const liked = new Set();
let lyricLines = [], lyricNodes = [], activeLyricIndex = -1;

const PLAY_LINES = ["Sounds good, bai!","Sige, play na!","Music is on 🔥","Hataw na!","Nindot paminawon, bai!"];
const FAIL_LINES = "Can't load the local MP3. Click Add my songs, then pili-a ang david_music1.mp3.";
const rand = a => a[Math.floor(Math.random()*a.length)];

function time(s){ if(!Number.isFinite(s)) return "0:00"; return Math.floor(s/60)+":"+String(Math.floor(s%60)).padStart(2,"0"); }
function notify(msg){ const t=$("toast"); t.textContent=msg; t.style.display="block"; clearTimeout(notify.t); notify.t=setTimeout(()=>t.style.display="none",2000); }

function cardHTML(t,sub){
  return `<article class="card${t.index===current?" playing":""}" data-index="${t.index}">
    <div class="cover" style="background:linear-gradient(135deg,${t.colors[0]},${t.colors[1]})">${t.img?`<img src="${t.img}" alt="${t.title} cover" class="cover-img">`:`<span>${t.emoji}</span>`}</div>
    <button class="card-play" data-play="${t.index}" aria-label="Play ${t.title}">▶</button>
    <h3>${t.title}</h3><p>${sub}</p></article>`;
}

function render(){
  let shown;
  if(view==="liked"){
    shown = [...liked].map(i=>({...tracks[i],index:i}));
    grid.innerHTML = shown.length ? shown.map(t=>cardHTML(t,t.artist+" · Liked")).join("") : `<div class="empty">No liked songs yet, bai. Tap ♡ while a song is playing para ma-save diri.</div>`;
  } else {
    shown = tracks.map((t,i)=>({...t,index:i})).filter(t=>(filter==="All"||t.genre===filter)&&`${t.title} ${t.artist} ${t.genre}`.toLowerCase().includes(query));
    grid.innerHTML = shown.length ? shown.map(t=>cardHTML(t,`${t.artist} · ${t.genre}`)).join("") : `<div class="empty">Nothing found, bai. Sulayi og lain nga search or add your own song.</div>`;
  }
  $("resultCount").textContent = shown.length + " TRACKS";
}

function setTitle(text){ $("sectionTitle").textContent = text; }

function updateLyrics(force=false){
  if(!lyricLines.length) return;
  const currentTime = audio.currentTime;
  let low = 0, high = lyricLines.length - 1, active = -1;
  while(low<=high){
    const middle = Math.floor((low+high)/2);
    if(lyricLines[middle].time<=currentTime){ active=middle; low=middle+1; }
    else high=middle-1;
  }
  if(active===activeLyricIndex && !force) return;
  if(activeLyricIndex>=0) lyricNodes[activeLyricIndex].classList.remove("active");
  activeLyricIndex = active;
  if(active>=0 && lyricLines[active].text){
    const line = lyricNodes[active];
    line.classList.add("active");
    line.scrollIntoView({block:"center",behavior:window.matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth"});
  }
}

function renderLyrics(track){
  const lyricsBox = $("lyricsBox");
  lyricLines = (window.SONATA_SYNCED_LYRICS?.[track.title] || []).filter(line=>
    !/^\[(?:verse|chorus|bridge|intro|outro|pre-chorus)\b/i.test(line.text) &&
    !/^(?:lyrics by|radiohead - creep)$/i.test(line.text)
  );
  lyricNodes = [];
  activeLyricIndex = -1;
  lyricsBox.replaceChildren();
  if(!lyricLines.length){
    lyricsBox.textContent = track.lyrics || "No lyrics available for this song, bai.";
    return;
  }
  lyricLines.forEach((line,index)=>{
    const node = document.createElement("span");
    node.className = line.text ? "lyric-line" : "lyric-line lyric-gap";
    node.dataset.lyricIndex = index;
    node.textContent = line.text || " ";
    lyricsBox.appendChild(node);
    lyricNodes.push(node);
  });
  updateLyrics();
}

function loadTrack(i, autoplay=true){
  current = (i+tracks.length)%tracks.length;
  const t = tracks[current];
  audio.src = t.url;
  $("nowTitle").textContent = t.title; $("nowArtist").textContent = t.artist;
  $("likeBtn").textContent = liked.has(current) ? "♥" : "♡";
  $("progress").value = 0; $("elapsed").textContent = "0:00"; $("duration").textContent = "0:00";
  const lyricsTitle = $("lyricsTitle");
  renderLyrics(t);
  if(lyricsTitle){ lyricsTitle.textContent = t.title + " — Lyrics"; }
  render();
  if(autoplay) play();
}

async function play(){
  if(current<0) loadTrack(0,false);
  try{ await audio.play(); }
  catch(e){ setPlaying(false); notify(FAIL_LINES); }
}
function pause(){ audio.pause(); }
function setPlaying(p){
  playing = p;
  $("playBtn").textContent = p ? "Ⅱ" : "▶";
  $("playBtn").title = p ? "Pause" : "Play";
  $("miniCover").classList.toggle("spin", p);
  document.querySelector(".hero-pic").classList.toggle("dance", p);
}
function next(){
  if(shuffle && tracks.length>1){ let n; do{ n=Math.floor(Math.random()*tracks.length); }while(n===current); loadTrack(n); }
  else loadTrack(current+1);
}
function previous(){ if(audio.currentTime>3) audio.currentTime=0; else loadTrack(current-1); }

function goHome(){ view="home"; filter="All"; query=""; $("searchInput").value=""; document.querySelectorAll(".chip").forEach(c=>c.classList.toggle("active",c.dataset.filter==="All")); setTitle("Para nimo, bai"); render(); }

/* ---------- Saved songs (IndexedDB) so uploads survive refresh ---------- */
let db = null;
function openDB(){
  return new Promise((resolve,reject)=>{
    let request;
    try{
      request = indexedDB.open("spotibai",1);
    }catch(error){
      reject(error);
      return;
    }
    request.onupgradeneeded = ()=>request.result.createObjectStore("songs",{keyPath:"id",autoIncrement:true});
    request.onsuccess = ()=>{ db=request.result; resolve(); };
    request.onerror = ()=>reject(request.error || new Error("Could not open song storage."));
    request.onblocked = ()=>reject(new Error("Song storage is blocked by another Spotibai tab."));
  });
}
function saveSong(title,blob){
  return new Promise((resolve,reject)=>{
    if(!db){ reject(new Error("Song storage is not available.")); return; }
    let transaction;
    try{
      transaction = db.transaction("songs","readwrite");
      transaction.objectStore("songs").add({title,blob});
    }catch(error){
      reject(error);
      return;
    }
    transaction.oncomplete = ()=>resolve();
    transaction.onerror = ()=>reject(transaction.error || new Error("Could not save this song."));
    transaction.onabort = ()=>reject(transaction.error || new Error("Saving this song was cancelled."));
  });
}
function addUserTrack(title,blob){
  tracks.push({title,artist:"My Library",genre:"Mine",emoji:"😤",colors:["#2e9bff","#0a3a8a"],url:URL.createObjectURL(blob)});
}
function loadSaved(){
  return new Promise((resolve,reject)=>{
    if(!db){ reject(new Error("Song storage is not available.")); return; }
    let request;
    try{
      request = db.transaction("songs").objectStore("songs").getAll();
    }catch(error){
      reject(error);
      return;
    }
    request.onsuccess = ()=>{ request.result.forEach(s=>addUserTrack(s.title,s.blob)); resolve(); };
    request.onerror = ()=>reject(request.error || new Error("Could not restore saved songs."));
  });
}

/* ---------- Events ---------- */
grid.addEventListener("click",e=>{
  const b = e.target.closest("[data-play]"), c = e.target.closest(".card");
  if(b) loadTrack(Number(b.dataset.play)); else if(c) loadTrack(Number(c.dataset.index));
});
$("playBtn").onclick = ()=> playing ? pause() : play();
$("heroPlay").onclick = ()=>{ current<0 ? loadTrack(0) : play(); notify(rand(PLAY_LINES)); };
$("lyricsClose").onclick = ()=>{ $("lyricsModal").classList.remove("open"); };
$("lyricsOverlay").onclick = e=>{ if(e.target===e.currentTarget) $("lyricsModal").classList.remove("open"); };
$("nextBtn").onclick = next; $("prevBtn").onclick = previous;
$("shuffleBtn").onclick = ()=>{ shuffle=!shuffle; $("shuffleBtn").classList.toggle("selected",shuffle); notify(shuffle?"Shuffle on—bahala na ta asa 🎲":"Shuffle off na"); };
$("repeatBtn").onclick = ()=>{ repeat=!repeat; $("repeatBtn").classList.toggle("selected",repeat); notify(repeat?"Repeat on—balik ta ani 🔁":"Repeat off na"); };
$("likeBtn").onclick = ()=>{
  if(current<0) return notify("Choose a song first, bai—pili sa imong library");
  liked.has(current) ? liked.delete(current) : liked.add(current);
  $("likeBtn").textContent = liked.has(current) ? "♥" : "♡";
  notify(liked.has(current) ? "Added to Liked Songs—nindot ni!" : "Removed from Liked Songs na");
  if(view==="liked") render();
};
$("volume").oninput = e => audio.volume = Number(e.target.value); audio.volume = .7;
$("lyricsBtn").onclick = ()=>{ $("lyricsModal").classList.add("open"); updateLyrics(true); };
$("searchInput").oninput = e=>{ view="home"; query=e.target.value.trim().toLowerCase(); setTitle(query?"Search results · Mga resulta":"Para nimo, bai"); render(); };
document.querySelectorAll(".chip").forEach(b=>b.onclick=()=>{ view="home"; filter=b.dataset.filter; document.querySelectorAll(".chip").forEach(x=>x.classList.toggle("active",x===b)); setTitle("Para nimo, bai"); render(); });
$("allSongsLink").onclick = ()=>{ goHome(); setTitle("All Songs · Tanang kanta"); };
$("likedLink").onclick = ()=>{ view="liked"; setTitle("Liked Songs · Mga ganahan"); render(); };
document.querySelectorAll(".nav a").forEach(a=>a.onclick=e=>{ e.preventDefault(); if(a.dataset.view==="search") $("searchInput").focus(); else goHome(); });
$("back").onclick = goHome;
$("forward").onclick = ()=>notify("No more forward, bai—naa na ta diri.");
$("profileBtn").onclick = ()=>notify(rand(["You're the star, bai 😤","Logged in as Bai—amping!","Smile lang ta, bai!"]));

function pickFiles(){ $("fileInput").click(); }
$("addMusic").onclick = pickFiles; $("addMusicSide").onclick = pickFiles;
$("fileInput").onchange = async e=>{
  const files = [...e.target.files].filter(f=>f.type.startsWith("audio/")||/\.(mp3|wav|ogg|m4a|flac|aac)$/i.test(f.name));
  e.target.value = "";
  if(!files.length) return;
  let saved = 0, notSaved = 0;
  for(const file of files){
    const title = file.name.replace(/\.[^.]+$/,"");
    addUserTrack(title,file);
    try{
      await dbReady;
      await saveSong(title,file);
      saved++;
    }catch(error){
      console.error("Could not save song for offline use:",error);
      notSaved++;
    }
  }
  view="home"; filter="Mine";
  document.querySelectorAll(".chip").forEach(c=>c.classList.toggle("active",c.dataset.filter==="Mine"));
  setTitle("My Songs · Imong mga kanta"); render();
  notify(notSaved ? `${saved} saved; ${notSaved} couldn't be saved for next time. Keep a copy of the file, bai.` : `${saved} song(s) saved for next time—payts na, bai!`);
};

audio.addEventListener("timeupdate",()=>{ if(audio.duration){ $("progress").value=audio.currentTime/audio.duration*100; $("elapsed").textContent=time(audio.currentTime); $("duration").textContent=time(audio.duration); } updateLyrics(); });
audio.addEventListener("seeked",updateLyrics);
$("progress").oninput = e=>{ if(audio.duration) audio.currentTime = Number(e.target.value)/100*audio.duration; };
audio.addEventListener("ended",()=>{ if(repeat){ audio.currentTime=0; play(); } else next(); });
audio.addEventListener("play",()=>setPlaying(true));
audio.addEventListener("pause",()=>setPlaying(false));
audio.addEventListener("error",()=>{ if(audio.src) notify(FAIL_LINES); });

const dbReady = openDB();
dbReady.then(loadSaved).then(render).catch(error=>{
  console.error("Could not restore saved songs:",error);
  render();
  notify("Saved songs aren't available in this browser. Add songs again in a browser that allows local storage, bai.");
});
